#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

int calculateBill(int units) {
    int bill = 0;
    if (units <= 100) {
        bill = units * 3;
    } else if (units <= 200) {
        bill = 100 * 3 + (units - 100) * 5;
    } else {
        bill = 100 * 3 + 100 * 5 + (units - 200) * 8;
    }
    return bill;
}

int main(void) {
    int units;
    scanf("%d", &units);
    printf("%d\n", calculateBill(units));
    return 0;
}
